function migrate(id, fn) {
  if (db.prepare('SELECT 1 FROM migrations WHERE id=?').get(id)) return false;
  db.exec('BEGIN');
  try {
    const info = JSON.stringify(fn() ?? {});
    db.prepare('INSERT INTO migrations(id,at,info) VALUES(?,?,?)').run(id, new Date().toISOString(), info);
    db.exec('COMMIT'); console.log('Migratsiya bajarildi:', id, info); return true;
  } catch (e) { db.exec('ROLLBACK'); console.error('Migratsiya bajarilmadi (keyingi ishga tushishda qayta urinadi):', id, e.message); return false; }
}
