// ---------------------------------------------------------------- scoring
const VARS = ['A', 'B', 'C', 'D'];
const varOf = v => VARS.includes(String(v || '').toUpperCase()) ? String(v).toUpperCase() : '';
function keyFor(testId, grade, variant) {
  if (variant && variant !== 'A') return one('SELECT key FROM vkeys WHERE test_id=? AND grade=? AND variant=?', testId, grade, variant)?.key || '';
  return one('SELECT key FROM keys WHERE test_id=? AND grade=?', testId, grade)?.key || '';
}
// sinf bosqichi bo'yicha variantlar va savollar soni (titul va skaner uchun; kalitlarning o'zi emas)
function varInfo(testId) {
  const o = {};
  for (const k of all('SELECT grade,key FROM keys WHERE test_id=?', testId)) o[k.grade] = { v: ['A'], qn: k.key.length, nopt: k.key.includes('E') ? 5 : 4 };
  for (const k of all('SELECT grade,variant,key FROM vkeys WHERE test_id=? ORDER BY variant', testId)) { const g = (o[k.grade] ||= { v: [], qn: k.key.length, nopt: 4 }); g.v.push(k.variant); if (k.key.includes('E')) g.nopt = 5; }
  for (const l of all('SELECT l.grade,l.bank_id,b.name,b.nopt FROM tlinks l JOIN tbank b ON b.id=l.bank_id WHERE l.test_id=?', testId)) {
    const g = (o[l.grade] ||= { v: [], qn: 0, nopt: 4 }); g.bank = { id: l.bank_id, name: l.name }; g.nopt = Math.max(g.nopt, l.nopt || 4);
  }
  const t100 = is100(testId); for (const g of Object.keys(o)) { o[g].locked = gradeLocked(testId, +g); if (o[g].qn && t100) o[g].w = wFor(testId, +g, o[g].qn); }
  return o;
}
// imtihonda shu sinf bosqichiga birorta natija (kelmadi ham) kiritilgan bo'lsa, testi va kalitlari qulflanadi
const gradeLocked = (testId, g) => !!one('SELECT 1 FROM results r JOIN students s ON s.id=r.student_id JOIN classes c ON c.id=s.class_id WHERE r.test_id=? AND c.grade=? AND c.school_id<>? LIMIT 1', testId, g, demoIds().school || -1);
// Savol ballari: savollar osondan qiyinga, 5 tadan guruh; har guruh bali oshib boradi, jami har doim 100.
const W_TABLE = { 20: [3.5, 4.5, 5.5, 6.5], 25: [3, 3.5, 4, 4.5, 5], 30: [2, 2.5, 3, 3.5, 4, 5] };
const r2 = x => Math.round(x * 100) / 100;
function defW(n) {
  n = Math.max(1, Math.min(50, n | 0)); const sizes = []; for (let i = 0; i < n; i += 5) sizes.push(Math.min(5, n - i));
  const k = sizes.length; let g;
  if (W_TABLE[n]) g = W_TABLE[n].slice();
  else {
    const raw = sizes.map((_, i) => k > 1 ? 1 + 0.9 * i / (k - 1) : 1), tot = raw.reduce((a, x, i) => a + x * sizes[i], 0);
    g = raw.map(x => Math.round(x * 100 / tot * 2) / 2);
    let diff = 100 - g.reduce((a, x, i) => a + x * sizes[i], 0), i = k - 1, guard = 200;
    while (Math.abs(diff) >= 0.5 * sizes[i] - 1e-9 && guard--) { const st = Math.sign(diff) * 0.5; g[i] += st; diff -= st * sizes[i]; i = i > 0 ? i - 1 : k - 1; }
  }
  const w = []; sizes.forEach((sz, i) => { for (let j = 0; j < sz; j++) w.push(g[i]); });
  const rest = r2(100 - w.reduce((a, x) => a + x, 0)); if (rest) w[n - 1] = r2(w[n - 1] + rest);
  return w;
}
const cleanW = (w, n) => Array.isArray(w) && w.length === n && w.every(x => typeof x === 'number' && x >= 0 && x <= 100) && Math.abs(w.reduce((a, x) => a + x, 0) - 100) < 0.01 ? w.map(r2) : null;
function wFor(testId, grade, n) { const r = one('SELECT w FROM wts WHERE test_id=? AND grade=?', testId, grade); let w = null; try { w = r && cleanW(JSON.parse(r.w), n); } catch (e) { } return w || defW(n); }
const is100 = testId => one('SELECT scoring FROM tests WHERE id=?', testId)?.scoring === '100';
// teng ball bo'lsa o'rin: qiyin guruhlar (16–20, 11–15 …) bo'yicha to'g'ri javoblar, keyin oxirgi savoldan boshlab
function tieCmp(a, b) { const x = a.bits || '', y = b.bits || ''; if (!x || !y || x.length !== y.length || a.qn !== 100) return 0; const n = x.length, one = (s, i, j) => [...s.slice(i, j)].filter(c => c === '1').length;
  for (let g = Math.floor((n - 1) / 5); g >= 0; g--) { const d = one(y, g * 5, g * 5 + 5) - one(x, g * 5, g * 5 + 5); if (d) return d; }
  for (let i = n - 1; i >= 0; i--) if (x[i] !== y[i]) return x[i] === '1' ? -1 : 1; return 0; }
const resCmp = (a, b) => { const d = (b.score ?? -1) - (a.score ?? -1); return Math.abs(d) > 1e-9 ? d : tieCmp(a, b); };
function score(testId, grade, mode, answers, bits, variant) {
  const key = keyFor(testId, grade, variant);
  if (!is100(testId)) return scoreOld(key, mode, answers, bits);
  const pts = b => { const w = wFor(testId, grade, b.length); return r2([...b].reduce((a, x, i) => a + (x === '1' ? w[i] : 0), 0)); };
  if (mode === 'harf') {
    const a = String(answers || '').toUpperCase().replace(/[^A-E-]/g, '-');
    if (!key) return { answers: a, bits: '', score: null, qn: 100, ok: null, nq: a.length || 20 };
    const b = [...key].map((k, i) => (a[i] && a[i] === k ? '1' : '0')).join('');
    return { answers: a.padEnd(key.length, '-').slice(0, key.length), bits: b, score: pts(b), qn: 100, ok: [...b].filter(x => x === '1').length, nq: key.length };
  }
  const n = key ? key.length : 20;
  const b = String(bits || '').replace(/[^01]/g, '0').padEnd(n, '0').slice(0, n);
  return { answers: '', bits: b, score: pts(b), qn: 100, ok: [...b].filter(x => x === '1').length, nq: n };
}
// eski tizim (100 ballik tizimdan oldingi imtihonlar): ball = to'g'ri javoblar soni
function scoreOld(key, mode, answers, bits) {
  if (mode === 'harf') {
    const a = String(answers || '').toUpperCase().replace(/[^A-E-]/g, '-');
    if (!key) return { answers: a, bits: '', score: null, qn: a.length || 20, ok: null, nq: null };
    const b = [...key].map((k, i) => (a[i] && a[i] === k ? '1' : '0')).join(''); const n = [...b].filter(x => x === '1').length;
    return { answers: a.padEnd(key.length, '-').slice(0, key.length), bits: b, score: n, qn: key.length, ok: n, nq: key.length };
  }
  const qn = key ? key.length : 20;
  const b = String(bits || '').replace(/[^01]/g, '0').padEnd(qn, '0').slice(0, qn); const n = [...b].filter(x => x === '1').length;
  return { answers: '', bits: b, score: n, qn, ok: n, nq: qn };
}
// faqat umumiy son ma'lum bo'lsa (qaysi savol to'g'riligi noma'lum) — ball ulush bo'yicha
const ballOfCount = (ok, n) => Math.round(ok / n * 200) / 2;
function rescoreTest(testId) {
  const rows = all(`SELECT r.id,r.mode,r.answers,r.bits,r.variant,c.grade FROM results r JOIN students s ON s.id=r.student_id
    JOIN classes c ON c.id=s.class_id WHERE r.test_id=? AND r.absent=0 AND r.mode!='ball'`, testId);
  for (const r of rows) { const s = score(testId, r.grade, r.mode, r.answers, r.bits, r.variant); run('UPDATE results SET bits=?,score=?,qn=?,ok=?,nq=? WHERE id=?', s.bits, s.score, s.qn, s.ok, s.nq, r.id); }
  return rows.length;
}

// announcement = CEO + jamoa sardori (if a sardor exists) both approved
function sardorIds() { return all("SELECT id,role,perms FROM users WHERE role='jamoa' AND active=1").filter(u => perms(u).sardor).map(u => u.id); }
function approvedState(testId, schoolId) {
  const ap = all('SELECT user_id FROM approvals WHERE test_id=? AND school_id=?', testId, schoolId).map(r => r.user_id);
  const ceo = one("SELECT id FROM users WHERE role='ceo'").id;
  const sard = sardorIds();
  const ceoOk = ap.includes(ceo), sardOk = !sard.length || sard.some(id => ap.includes(id));
  const ann = one('SELECT at FROM announcements WHERE test_id=? AND school_id=?', testId, schoolId);
  return { ceo: ceoOk, sardor: sardOk, hasSardor: sard.length > 0, done: !!ann, at: ann?.at || null, by: ap };
}
const announced = (testId, schoolId) => !!one('SELECT 1 FROM announcements WHERE test_id=? AND school_id=?', testId, schoolId);
const finished = testId => announced(testId, 0);

// ---------------------------------------------------------------- state (what each role may see)
function state(u) {
  const P = perms(u);
  const tests = all('SELECT * FROM tests ORDER BY id DESC');
  const out = { me: { id: u.id, role: u.role, name: u.name, perms: P, consent: !!u.consent_at, avatar: u.avatar || '', phone: u.phone || '', school_id: u.school_id || null, class_id: u.class_id || null, pin_at: u.pin_at || null, created_at: u.created_at || null, has_pass: u.role === 'ceo' ? !!u.pass : undefined }, tests, perms: PERMS };
  if (isTeam(u)) {
    const DM = demoIds();
    out.schools = all('SELECT * FROM schools ORDER BY num').filter(x => x.id !== DM.school);
    out.classes = all('SELECT * FROM classes ORDER BY school_id,grade,name').filter(x => x.school_id !== DM.school);
    const okC = new Set(out.classes.map(c => c.id));
    out.students = all('SELECT id,class_id,name,phone,avatar,patronymic,flag FROM students WHERE active=1 ORDER BY name').filter(x => okC.has(x.class_id)).map(s => ({ ...s, avatar: kidPh(s.avatar) }));
    const okS = new Set(out.students.map(x => x.id));
    out.results = all('SELECT id,test_id,student_id,absent,mode,answers,bits,score,qn,entered_by,at,variant,ok,nq FROM results').filter(r => okS.has(r.student_id) || !one('SELECT 1 FROM students s JOIN classes c ON c.id=s.class_id WHERE s.id=? AND c.school_id=?', r.student_id, DM.school));
    if (!P.ceo && !P.kalit) for (const r of out.results) r.answers = r.answers ? r.answers.replace(/[A-E]/g, '•') : r.answers; // javoblar + belgilar = kalit; kalit huquqi yo'qlarga berilmaydi
    out.vinfo = Object.fromEntries(tests.map(t => [t.id, varInfo(t.id)]));
    out.bank = bankList();
    out.keys = {};
    for (const t of tests) {
      const visible = P.ceo || (P.kalit && ['tekshiruv', 'yakunlandi'].includes(t.status));
      out.keys[t.id] = visible ? Object.fromEntries(all('SELECT grade,key FROM keys WHERE test_id=?', t.id).map(k => [k.grade, k.key]))
        : Object.fromEntries(all('SELECT grade,length(key) n FROM keys WHERE test_id=?', t.id).map(k => [k.grade, '?'.repeat(k.n)]));
      if (visible) { const vk = {}; for (const k of all('SELECT grade,variant,key FROM vkeys WHERE test_id=?', t.id)) (vk[k.grade] ||= {})[k.variant] = k.key; (out.vkeys ||= {})[t.id] = vk; }
    }
    out.approvals = {};
    for (const t of tests) { out.approvals[t.id] = {}; for (const s of [{ id: 0 }, ...out.schools]) out.approvals[t.id][s.id] = approvedState(t.id, s.id); }
    out.team = all("SELECT id,role,name,phone,perms,active,last_login,avatar,pin FROM users WHERE role IN ('ceo','jamoa')").filter(x => !DM.set.has(x.id)).map(x => ({ ...x, perms: perms(x), pin: u.role === 'ceo' && !u._demo && x.role === 'jamoa' && x.active ? x.pin : undefined }));
    out.notes = all('SELECT * FROM notes ORDER BY at DESC');
    out.hints = hintsMap();
    Object.assign(out, extras(u, out));
    return out;
  }
  // school-side roles: results only after announcement
  let classIds = [];
  if (u.role === 'direktor') classIds = all('SELECT id FROM classes WHERE school_id=?', u.school_id).map(r => r.id);
  if (u.role === 'rahbar') classIds = [u.class_id];
  if (u.role === 'ota') {
    const p = phone9(u.phone);
    const kids = kidsOfPhone(p);
    classIds = [...new Set(kids.map(id => one('SELECT class_id FROM students WHERE id=?', id).class_id))];
  }
  const ph = classIds.map(() => '?').join(',') || 'NULL';
  out.classes = all(`SELECT id,school_id,name,grade,teacher_name,obuna${u.role === 'direktor' ? ',teacher_phone' : ''} FROM classes WHERE id IN (${ph})`, ...classIds);
  const schoolIds = [...new Set(out.classes.map(c => c.school_id))];
  out.schools = all(`SELECT id,num,name,raqam,tuman,viloyat${u.role === 'direktor' ? ',director_name,director_phone' : ''} FROM schools WHERE id IN (${schoolIds.map(() => '?').join(',') || 'NULL'})`, ...schoolIds);
  let studs = all(`SELECT id,class_id,name,phone,avatar,patronymic,jins FROM students WHERE active=1 AND class_id IN (${ph}) ORDER BY name`, ...classIds);
  if (u.role === 'rahbar') { const my = one('SELECT school_id,grade FROM classes WHERE id=?', u.class_id);
    out.moveTo = my ? all('SELECT id,name FROM classes WHERE school_id=? AND grade=? AND id<>? ORDER BY name', my.school_id, my.grade, u.class_id) : []; }
  if (u.role === 'ota') { const k = new Set(kidsOfPhone(phone9(u.phone))); out.children = studs.filter(s => k.has(s.id)).map(s => s.id); }
  const hm = ['rahbar', 'direktor'].includes(u.role) ? hintsMap() : {};
  out.students = studs.map(s => ({ id: s.id, class_id: s.class_id, name: s.name, patronymic: s.patronymic || '', jins: s.jins === 'a' || s.jins === 'e' ? s.jins : '', avatar: kidPh(s.avatar),
    ...(['rahbar', 'direktor'].includes(u.role) ? { phone: s.phone || '', extra: extraPhones(s.id), hint: hm[s.id] || '' } : {}) }));
  const visibleTests = tests.filter(t => schoolIds.some(sid => announced(t.id, sid)));
  out.tests = visibleTests.map(t => ({ ...t, finished: finished(t.id) }));
  const sIds = studs.map(s => s.id);
  out.results = [];
  for (const t of visibleTests) {
    for (const sid of schoolIds) {
      if (!announced(t.id, sid)) continue;
      const rows = all(`SELECT r.test_id,r.student_id,r.absent,r.bits,r.score,r.qn FROM results r JOIN students s ON s.id=r.student_id
        JOIN classes c ON c.id=s.class_id WHERE r.test_id=? AND c.school_id=?`, t.id, sid).filter(r => sIds.includes(r.student_id));
      out.results.push(...rows);
    }
  }
  if (u.role === 'ota') { // parents: other children only as class averages, never names
    const kids = new Set(out.children);
    const avg = {};
    for (const r of out.results) { const s = studs.find(x => x.id === r.student_id); const k = r.test_id + ':' + s.class_id; if (!r.absent) { (avg[k] ||= []).push(r.score / r.qn); } }
    out.classAvg = Object.fromEntries(Object.entries(avg).map(([k, v]) => [k, Math.round(v.reduce((a, b) => a + b, 0) / v.length * 1000) / 10]));
    out.results = out.results.filter(r => kids.has(r.student_id));
    out.students = out.students.filter(s => kids.has(s.id));
    out.classes = out.classes.filter(c => out.students.some(s => s.class_id === c.id));
  }
  // district figures only after the whole test is finished
  out.district = {};
  out.gifted = [];
  for (const t of out.tests) {
    if (!t.finished) continue;
    const rows = all(`SELECT r.student_id,r.score,r.qn,r.bits,c.grade,c.school_id FROM results r JOIN students s ON s.id=r.student_id JOIN classes c ON c.id=s.class_id
      WHERE r.test_id=? AND r.absent=0 AND r.score IS NOT NULL`, t.id).filter(r => u._demo || r.school_id !== demoIds().school); // namuna natijalar haqiqiy tuman ko'rsatkichiga qo'shilmaydi
    for (const g of [...new Set(rows.map(r => r.grade))]) {
      const gr = rows.filter(r => r.grade === g).sort((a, b) => b.score - a.score);
      out.district[t.id + ':' + g] = Math.round(gr.reduce((a, r) => a + r.score / r.qn, 0) / gr.length * 1000) / 10;
      // sinf rahbari: o'z maktabining shu sinf bosqichi o'rtachasi (solishtirish uchun)
      if (u.role === 'rahbar') { const my = gr.filter(r => r.school_id === schoolIds[0]); if (my.length) out.district[t.id + ':school:' + g] = Math.round(my.reduce((a, r) => a + r.score / r.qn, 0) / my.length * 1000) / 10; }
      // direktor: o'z maktabining tumandagi o'rni (boshqa maktablar nomi va bolalari ko'rsatilmaydi)
      if (u.role === 'direktor') {
        const by = {}; for (const r of gr) (by[r.school_id] ||= []).push(r.score / r.qn);
        const avgs = Object.entries(by).map(([k, v]) => [+k, v.reduce((a, b) => a + b, 0) / v.length]).sort((a, b) => b[1] - a[1]);
        const i = avgs.findIndex(x => x[0] === u.school_id); if (i >= 0) out.district[t.id + ':srank:' + g] = [avgs.filter(x => x[1] > avgs[i][1]).length + 1, avgs.length];
      }
      if (u.role === 'ota') for (const kid of out.children) { const i = gr.findIndex(r => r.student_id === kid); if (i >= 0) out.district[t.id + ':rank:' + kid] = [gr.filter(r => resCmp(r, gr[i]) < 0).length + 1, gr.length]; }
    }
  }
  for (const t of out.tests) for (const sid of schoolIds) if (announced(t.id, sid)) out.gifted.push(...giftedIds(t, sid).filter(id => out.students.some(s => s.id === id)).map(id => t.id + ':' + id));
  Object.assign(out, extras(u, out));
  return out;
}
// iqtidorli: o'zlashtirish darajasi bo'yicha — kamida gifted_min% olgan har bir o'quvchi (top % qoidasi olib tashlandi, 2026-11-01)
function giftedIds(t, schoolId) {
  const rows = all(`SELECT r.student_id,r.score,r.qn,r.bits,c.grade,c.school_id FROM results r JOIN students s ON s.id=r.student_id JOIN classes c ON c.id=s.class_id
    WHERE r.test_id=? AND r.absent=0 AND r.score IS NOT NULL AND s.active=1`, t.id).filter(r => !schoolId || r.school_id === schoolId);
  const DSg = demoIds().school; return rows.filter(r => (DSg && schoolId === DSg) || r.school_id !== DSg).filter(r => r.qn > 0 && r.score / r.qn * 100 >= t.gifted_min - 1e-9).map(r => r.student_id);
}

