  d: a => /(ochirish|ochirildi|chiqarish|tuzatish|bekor|tozalash|qaytarish|tiklash|almashtirildi)$/.test(a) || a === 'natija.kelmadi_hammasi',
  c: a => a.startsWith('sertifikat.'),
