  const kind = AUDIT_KIND[b.kind] || null, uid = b.user_id != null && b.user_id !== '' ? +b.user_id : null, sch = +b.school_id || 0;
  const q = String(b.q || '').toLowerCase().replace(/[`‘’'ʻʼ]/g, "'").trim();
