      if (DEMO_SET.has(r.user_id)) continue; // namuna kabinetdagi harakatlar tarixga chiqmaydi
      if (kind && !kind(r.action)) continue;
      if (uid != null && r.user_id !== uid) continue;
      const o = auditRow(r);
