      o.who = whoName(r.user_id);
      if (q && !`${o.stu || ''} ${o.who} ${o.num ? mkNum(o.num) + '' : ''} ${o.cls || ''} ${o.detail.name || ''} ${o.detail.child || ''} ${o.test || ''} ${o.detail.code || ''}`.toLowerCase().replace(/[`‘’'ʻʼ]/g, "'").includes(q)) continue;
