  cnt.__all = Object.fromEntries(all('SELECT topic,count(*) n FROM probs WHERE active=1 GROUP BY topic').map(r => [r.topic, r.n])); pbAddSrcCounts(g, cnt, false); delete cnt.__all;
  ex.pbTopics = (PB_TOPICS[g] || []).map(([grp, l]) => [grp, l.filter(([c]) => !PB_LOCKED(c)).map(([c, n]) => [c, n, cnt[c] || 0, !!MAVZU[c]])]).filter(([, l]) => l.length);
