  if (!clsName(r.sinf)) return { status: 'kutilmoqda', msg: RX_KUT + 'Tekshirilgach, PIN kodingiz shu yerga keladi.' };
  const sc = rxSchool(r, true); let cl = rxClass(sc, r.sinf, false);
