const failBlocked = k => { const o = fails.get(k); return !!(o && o.until > Date.now()); };
setInterval(() => { const t = Date.now(); for (const [k, o] of fails) if (t - o.first > FAIL_WIN && o.until < t) fails.delete(k); }, 10 * 60e3).unref();
